      "position_constraint": "Position constraint: ",
      "post_weld_heat_treatment_pwht": "🌡 Post-Weld Heat Treatment (PWHT)",
      "post_weld_heat_treatment_when_needed": "Post-weld heat treatment + when needed",
      "ppe_safety": "PPE & Safety",
